use std::io::{self, Write};

use serde::Serialize;

use crate::cli::OutputFormat;

/// Writes a JSON document that is not a report, such as the intent `release inspect` echoes, which carries its own
/// version. A report goes through [`emit_report`], the only way to get the envelope and `schemaVersion`; this is
/// crate-private so a command cannot bypass it.
pub(crate) fn write_document<W: io::Write, S: Serialize + ?Sized>(w: &mut W, val: &S) -> io::Result<()> {
    let text = serde_json::to_string_pretty(val)?;
    writeln!(w, "{text}")
}

/// Writes the JSON error envelope that `format_error_json` builds.
pub fn write_error_json<W: io::Write>(w: &mut W, envelope: &serde_json::Value) -> io::Result<()> {
    write_document(w, envelope)
}

/// Serializes any `Report` value to the one JSON success envelope every
/// command shares: `{schemaVersion, command, dryRun, ...payload,
/// diagnostics}`. `command` comes from `R::COMMAND`, `schemaVersion` from
/// the payload's own `Report::schema_version()` (re-inserted at the top
/// level rather than left flattened, so it appears exactly once). Callers
/// pass their `Report` to this function instead of hand-building a JSON envelope.
pub fn emit_report<W: io::Write, R: callisto_model::Report>(w: &mut W, val: &R, dry_run: bool) -> io::Result<()> {
    let mut value = serde_json::to_value(val)?;
    if let serde_json::Value::Object(map) = &mut value {
        map.insert("schemaVersion".to_string(), serde_json::json!(val.schema_version()));
        map.insert("command".to_string(), serde_json::json!(R::COMMAND));
        map.insert("dryRun".to_string(), serde_json::json!(dry_run));
    }
    let text = serde_json::to_string_pretty(&value)?;
    writeln!(w, "{text}")
}

/// Writes `bytes` to stdout. A closed reading end (e.g. `callisto ... | head`)
/// is not a failure -- it's the normal way a consumer stops reading -- so a
/// `BrokenPipe` is swallowed here instead of propagating, which is what
/// makes this the one sink callers use in place of `println!` (which panics
/// on that same condition).
pub fn write_stdout(bytes: &[u8]) -> io::Result<()> {
    write_swallowing_broken_pipe(&mut io::stdout(), bytes)
}

/// The actual classification [`write_stdout`] applies, pulled out so a test
/// can exercise it against a real closed pipe without touching the
/// process's real (unredirectable, in-process) stdout fd.
fn write_swallowing_broken_pipe<W: Write>(w: &mut W, bytes: &[u8]) -> io::Result<()> {
    match w.write_all(bytes) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => Ok(()),
        Err(e) => Err(e),
    }
}

/// Writes one line (plus trailing newline) through [`write_stdout`].
pub fn emit_line(line: &str) -> io::Result<()> {
    write_stdout(format!("{line}\n").as_bytes())
}

/// Writes one line to stderr -- for interactive wizard narration
/// (`callisto add`'s step prompts), which must stay off stdout so a script
/// piping stdout never sees prompt text mixed into a report or changeset preview.
pub fn prompt_line(line: &str) {
    eprintln!("{line}");
}

pub fn log_line(format: OutputFormat, line: &str) -> io::Result<()> {
    match format {
/// guarantees a stable shape regardless of which [`CliError`] variant is
/// serialized.
pub fn format_error_json(command: &str, dry_run: bool, err: &CliError) -> serde_json::Value {
    let code = err.code().map(|c| c.to_string()).unwrap_or_else(|| "E000".to_string());
    let help = err.help().map(|h| h.to_string());
    let path = err.path().map(|p| p.display().to_string());
    serde_json::json!({
        "schemaVersion": callisto_model::SCHEMA_VERSION,
        "command": command,
        "dryRun": dry_run,
        "error": {
            "code": code,
            "message": err.to_string(),
            "help": help,
            "path": path,
        }
    })
}

impl CliError {
    pub fn exit_kind(&self) -> ExitKind {
        match self {
            Self::Graph(error) => error.exit_kind(),
            Self::Config(error) => error.exit_kind(),
            Self::NotATty
            | Self::ReleaseArtifactManifestDryRun
            | Self::ReleasePlanDryRun
            | Self::ReleaseExecuteDryRun
            | Self::ReleasePendingFromInvalid { .. }
            | Self::ReleaseBuildPythonDryRun
            | Self::ReleaseCommitInvalid { .. }
            | Self::ReleaseDecisionOutsideSource { .. }
            | Self::ReleaseDecisionPathInvalid { .. }
            | Self::ReleasePackageInvalid { .. }
            | Self::ReleaseOrchestrationRevisionInvalid { .. }
            | Self::ReleaseArtifactRepositoryInvalid { .. }
            | Self::ReleaseOrchestrationFlagsRequired
            | Self::ReleaseUnexpectedArtifactInputs
            | Self::ReleaseMissingArtifactInputs
            | Self::ReleasePrArgJsonInvalid { .. }
            | Self::ReleaseForgeRepositoryMismatch { from_flag: true, .. }
            | Self::InitRequiresYes { .. }
            | Self::InitMissingFlags { .. }
            | Self::InitWorkflowFlagsConflict
            | Self::InitFlagRequiresArtifactTarget { .. }
            | Self::AddInvalidPackageSpec { .. }
            | Self::InvalidSeverity { .. }
            | Self::AddSummaryRequired
            | Self::AddDuplicatePackage { .. }
            | Self::AddSummaryEmpty
            | Self::VersionEmitDryRun { .. }
            | Self::PreTagEmpty
            | Self::ReleasePrCommitPlanDryRun
            | Self::HelpUnknownCommand { .. } => ExitKind::Usage,
            _ => ExitKind::Runtime,
        }
    }
}

#[derive(Debug, thiserror::Error, Diagnostic)]
#[non_exhaustive]
pub enum CliError {
    #[error(transparent)]
    #[diagnostic(transparent)]
    Graph(#[from] GraphError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    Locate(#[from] LocateError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    Config(#[from] ConfigError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    Command(#[from] CommandError),

    #[error(transparent)]
    #[diagnostic(
        code(E211),

    #[error(transparent)]
    #[diagnostic(transparent)]
    VersionParse(#[from] VersionParseError),
}

/// Whether a failure is bad command-line input (exit 2) or anything else (exit 1).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ExitKind {
    /// A bad or missing flag or argument value, or a bad flag combination, caught after parsing.
    Usage,
    /// Workspace, config, git, registry or release state.
    Runtime,
}

impl GraphError {
    pub fn exit_kind(&self) -> ExitKind {
        match self {
            Self::Config(error) => error.exit_kind(),
            Self::InitInvalidForgeRepository { .. }
            | Self::InitInvalidTargetTriple { .. }
            | Self::InitForgeRepositoryMismatch { .. }
            | Self::InitInvalidProductPackage { .. }
            | Self::UnknownPackage { .. }
            | Self::PendingFromNotReleaseCommit { .. }
            | Self::ReleaseSelectionInvalid {
                reason: ReleaseSelectionInvalidReason::Duplicate,
                ..
            }
            | Self::TagInvalid { .. } => ExitKind::Usage,
            _ => ExitKind::Runtime,
        }
    }

    /// E102 for `id`, suggesting up to three of `known` whose names are a small edit away.
    pub fn unknown_package(id: PackageId, known: impl IntoIterator<Item = PackageId>) -> Self {
        let hint = did_you_mean(&id, known);
        Self::UnknownPackage { id, hint }
    }

    /// The one filesystem path this error is about, when it carries it as a structured field.
    pub fn path(&self) -> Option<&std::path::Path> {
        match self {
            Self::Config(error) => error.path(),
            Self::ParseChangeset { path, .. }
            | Self::UnexpectedManifestVersion { path, .. }
            | Self::PartialVersionRun { path, .. }
            | Self::ApplyIo { path, .. }
            | Self::UnsafeArtifactPath { path, .. }
            | Self::ArtifactRead { path, .. }
            | Self::ArtifactBytesMismatch { path }
            | Self::ArtifactAttestation { path, .. }
            | Self::ReleaseInputRead { path, .. }
            | Self::ReleaseDecisionDecode { path, .. }
            | Self::InitAlreadyInitialized { path }
            | Self::InitIo { path, .. }
            | Self::InitWorkflowExists { path } => Some(path),
            _ => None,
        }
    }
}

impl ConfigError {
    pub fn exit_kind(&self) -> ExitKind {
        match self {
            // The same reference read from callisto.toml is a config error, not usage.
            Self::ColonReference { context, .. } | Self::BareReference { context, .. } if context.starts_with("--") => {
                ExitKind::Usage
            }
            _ => ExitKind::Runtime,
        }

