/// Release notes for a package: its changelog section, else generated notes and why.
///
/// # Errors
///
/// The changelog exists but cannot be read.
pub(crate) fn release_notes(
    root: &Path,
    changelog: Option<&Path>,
    version: &Version,
) -> Result<ReleaseNotes, GraphError> {
